head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
scwin.gDepCd = js_dep_cd;
scwin.gEmpNo = js_emp_no;
scwin.gLdMktTp = js_market;
scwin.gParamObj;
scwin.vScrenID = 'ULDSTF30003.xml';
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};
scwin.fn_Init = function() {
    if (js_market == "9") {
        $c.stf.setObjectValue(rdo_MKT_ID, scwin.gLdMktTp);
        rdo_MKT_ID.setDisabled(false);
    } else {
        $c.stf.setObjectValue(rdo_MKT_ID, scwin.gLdMktTp);
        rdo_MKT_ID.setDisabled(true);
    }
};
scwin.fn_resizeToWin = function() {
    frame.Width = 480;
    frame.Height = 530;
};
scwin.fn_getParam = function() {
    // opener로 부터 param을 받는다.
    var parentWin = $c.frame.path("../");
    var paramObj = parentWin.scwin.gParamObj;
    var ISURCD = paramObj.param0;
    $c.stf.setObjectValue(txb_ISUR_CD, ISURCD);
};
scwin.fn_setParam = function() {
    // child에 param을 넘긴다.
    var argv = fn_setParam.arguments;
    var argc = fn_setParam.arguments.length;
    scwin.gParamObj = new Array(argc); // 초기화
    for (var i = 0; i < argc; i++) // actual arguments

    {
        eval("gParamObj.param" + i + " = argv[" + i + "]");
    }
    return true;
};
scwin.fn_listDisclosure = function() {
    //var MARKET_FLAG = getObjectValue(rdo_Tab1_Market_Flag);	
    var url = "/DisclosureSchedule.do?method=listDisclosure";
    url += "&MKT_ID=" + $c.stf.getObjectValue(rdo_MKT_ID);
    url += "&FORM_NM=" + $c.stf.getObjectValue(txb_FORM_KOR_NM);
    url += "&SCREN_ID=" + scwin.vScrenID;
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    dts_Discls.DataID = encodeURI(url);
    dts_Discls.Reset();
};
scwin.setAcpt_No = async function(GridID, row, ColID) {
    var objDataID = document.all(GridID.DataID); // 가져오는 방식이 좀 특이하다..

    var vFORM_CD = objDataID.getCellData(row, "FORM_CD");
    var vFORM_KOR_NM = objDataID.getCellData(row, "FORM_KOR_NM");
    var parentWin = $c.frame.path("../");
    if (parentWin.txb_Tab1_RptCd == null) {
        // 유가.
        $c.stf.setObjectValue(parentWin.txb_FORM_CD, vFORM_CD);
        $c.stf.setObjectValue(parentWin.txb_FORM_KOR_NM, vFORM_KOR_NM);
    } else {
        $c.stf.setObjectValue(parentWin.txb_Tab1_RptCd, vFORM_CD);
        $c.stf.setObjectValue(parentWin.txb_Tab1_RptNm, vFORM_KOR_NM);
    }
    await $c.frame.CloseFrame();
};
scwin.fn_HideDebugCtrls = function() {
    // 키값으로 사용하지만 화면상에 표시될 필요가 없는 것들
    $c.stf.showObj(panel_debug, false);
};
scwin.grd_Discls_OnDblClick = function(row, colid) {
    scwin.setAcpt_No(grd_Discls, row, colid);
};
scwin.dts_Discls_OnLoadCompleted = function(rowcount) {
    $c.stf.FillGridHeaderTotalCnt(rowcount, panel_page);
    //setObjectValue(txb_TotalCnt, "총 " + FormatNumberEx(rowcount) + " 건");

};
scwin.rdo_MKT_ID_OnSelChange = function() {
    //fn_listDisclosure();

};
scwin.gform_onload = function() {
    scwin.fn_HideDebugCtrls();
    $c.libRoundPanel.PanelToGroupBox(panel_1);
    scwin.fn_resizeToWin();
    scwin.fn_getParam();
    scwin.fn_Init();
    scwin.fn_listDisclosure();
    //MoveCenterOfParent();

};
scwin.btn_Search_onclick = function() {
    scwin.fn_listDisclosure();
};
scwin.txb_FORM_KOR_NM_onkeydown = function() {
    if (window.event.keyCode == "13") {
        scwin.fn_listDisclosure();
    }
};
